```tsx
import type { ReactElement } from "react";
import "./AlertBanner.css";

export interface AlertBannerProps {
  message: string;
  onRetry: () => void;
}

export function AlertBanner({ message, onRetry }: AlertBannerProps): ReactElement {
  return (
    <div className="alert-banner" role="alert">
      <p className="alert-banner__message">{message}</p>
      <button type="button" className="alert-banner__retry" onClick={onRetry}>
        Retry
      </button>
    </div>
  );
}
```

```css
.alert-banner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: clamp(0.5rem, 1.5vw, 1rem) clamp(0.75rem, 2vw, 1.25rem);
  padding: clamp(0.6rem, 1.5vw, 0.9rem) clamp(0.9rem, 2vw, 1.25rem);
  border: 1px solid var(--cresyl);
  border-radius: 12px;
  background: var(--cresyl-wash);
  color: var(--ink);
  font: inherit;
  font-size: clamp(0.875rem, 1.2vw, 1rem);
}

.alert-banner__message {
  flex: 1 1 16rem;
  min-width: 0;
  margin: 0;
  overflow-wrap: anywhere;
}

.alert-banner__retry {
  flex: 0 0 auto;
  margin-left: auto;
  padding: 0.4em 1.1em;
  border: 1px solid var(--ink);
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.alert-banner__retry:hover {
  background: var(--slide);
}

.alert-banner__retry:focus-visible {
  outline: 3px solid var(--cresyl);
  outline-offset: 3px;
}
